card_mod.style:
ha-card { border: 1px solid color-mix(in srgb, #8b5cf6 45%, transparent) !important; }
/* Quiet Hours preview */
ha-card { background: var(--ha-card-background, #151515) !important; border: 1px solid var(--ha-card-border-color, #303030) !important; border-radius: 16px !important; box-shadow: none !important; font-family: Figtree, sans-serif !important; }

icon.color:
[[[
  const value = parseInt(states['sensor.u_s_air_quality_index'].state, 10);
  if (value > 300) return '#FF6464';
  if (value > 200) return '#FF9A00';
  if (value > 150) return '#FFC400';
  if (value > 100) return '#FFFF00';
  if (value > 50) return '#31FF00';
  return '#9CFF9C';
]]]

[[[
  const level = states['sensor.u_s_air_pollution_level'].state;
  if (level == 'Hazardous') return '#FF6464';
  if (level == 'Very Unhealthy') return '#FF9A00';
  if (level == 'Unhealthy') return '#FFC400';
  if (level == 'Unhealthy for Sensitive Groups') return '#FFFF00';
  if (level == 'Moderate') return '#31FF00';
  return '#9CFF9C';
]]]

cards.style:
.card-content {
  padding: 0 !important;
}
ha-card {
  overflow: hidden;
  height: 100%;
  --ha-card-background: "rgba(0, 0, 0, 0.4)";
  --ha-card-box-shadow: "inset 0px 0px 10px 3px rgba(0, 0, 0, 0.5)";
}

styles.$:
.swiper-container {
  padding-bottom: 40px;
  overflow: hidden !important;
  height: 400px !important;  /* Adjust this value as needed */
}
.swiper-wrapper {
  height: 100% !important;
}
.swiper-slide {
  height: 100% !important;
  overflow-y: auto !important;
  overflow-x: hidden !important;
}
.swiper-pagination {
  bottom: 10px !important;
}
.swiper-pagination-bullet {
  width: 10px;
  height: 10px;
  margin: 0 6px;
}

cards.style:
ha-card {
  overflow: hidden;
  padding: 8px 0;
}
#root {
  display: flex;
  overflow-x: auto;
  overflow-y: hidden;
  white-space: nowrap;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;  /* Firefox */
  -ms-overflow-style: none;  /* Internet Explorer 10+ */
  padding: 4px 0;
  width: 100%;
}
#root::-webkit-scrollbar { 
  display: none;  /* WebKit */
}
#root > * {
  flex: 0 0 auto;
  margin-right: 8px;
  min-width: 48px; /* Minimum width of each card */
}
/* Force horizontal layout */
#root > horizontal-stack {
  display: flex;
  flex-wrap: nowrap;
  width: max-content;
}

custom_fields.light_count:
[[[
  var count = 0;
  if (states['light.string_lights']?.state === 'on') count++;
  if (states['light.front_door_lights']?.state === 'on') count++;
  return count > 0 ? count : '';
]]]

content.content:
[[[
  const state = entity.state;
  const isMorning = new Date().getHours() < 12;
  const mealType = isMorning ? "Breakfast" : "Dinner";
  const lastFed = hass.states[`input_datetime.zoey_last_fed_${isMorning ? 'morning' : 'afternoon'}`].state;

  let content = `### Zoey's ${mealType}\n\n`;
  if (state === 'fed') {
    content += '✅ Fed\n\n';
  } else if (state === 'overdue') {
    content += '❌ Overdue\n\n';
  } else {
    content += '⏳ Not fed yet\n\n';
  }
  if (lastFed && lastFed !== 'unknown') {
    const formattedTime = new Date(lastFed).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
    content += `Last fed: ${formattedTime}`;
  } else {
    content += 'No feeding time recorded';
  }
  return content;
]]]

state.value:
[[[
  const due = ['today', 'tomorrow'];
  const trash = states['sensor.garbage_pickup']?.state.toLowerCase();
  const recycle = states['sensor.recycling_pickup']?.state.toLowerCase();
  const is_due = due.includes(trash) || due.includes(recycle);
  return is_due && states['input_boolean.trash_out']?.state === 'off';
]]]

