custom_fields.body:
[[[
const st = id => states[id] ? states[id].state : undefined;
const house = Math.round(parseFloat(st('input_number.house_setpoint')));
const hsm = st('sensor.hub_hsm_status');
const hold = st('input_boolean.climate_manual_override_active') === 'on';
const rooms = [['climate.living_room_thermostat', 'Living Room'], ['climate.bedroom_thermostat', 'Bedroom'],
               ['climate.liam_s_room_thermostat', "Liam's Room"], ['climate.office_thermostat', 'Office']];
const temps = ['sensor.living_room_climate_temp', 'sensor.bedroom_temp_calibrated', 'sensor.liams_room_temperature', 'sensor.office_average_temp'].map(id => parseFloat(st(id))).filter(t => !isNaN(t));
const inside = temps.length ? (temps.reduce((a, b) => a + b, 0) / temps.length).toFixed(1) + '°' : '--';
let mode = hsm === 'armedAway' ? 'Away' : hsm === 'armedNight' ? 'Night schedule' : 'Following the schedule';
let color = 'var(--primary-text-color)';
if (hold) { mode = 'Holding ' + house + '°'; color = 'var(--warning-color)'; }
else if (hsm === 'armedAway') color = 'var(--warning-color)';
const heating = [], paused = [];
for (const [id, name] of rooms) {
  const s = states[id];
  if (!s) continue;
  const a = s.attributes || {};
  const doorPause = id === 'climate.living_room_thermostat' && st('input_select.living_room_climate_restore_mode') !== 'off';
  const windowPause = a.window_manager && a.window_manager.window_state === 'on';
  if (s.state === 'off' && (doorPause || windowPause)) paused.push(name);
  else if (s.state === 'heat' && (a.hvac_action === 'heating' || (a.power_percent || 0) > 0)) heating.push(name);
}
const parts = [];
if (heating.length) parts.push('Heating ' + heating.join(', '));
if (paused.length) parts.push(paused.join(', ') + ' paused');
const roomsLine = parts.length ? parts.join(' · ') : 'All rooms warm enough';
return `<div style="display:flex;align-items:center;gap:16px;width:100%">
  <div style="font-size:44px;font-weight:300;line-height:1">${isNaN(house) ? '--' : house}°</div>
  <div style="flex:1;min-width:0;text-align:left">
    <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--secondary-text-color)">House climate</div>
    <div style="font-size:15px;font-weight:600;color:${color};margin-top:2px">${mode}</div>
    <div style="font-size:13px;color:var(--secondary-text-color);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">Inside ${inside} · ${roomsLine}</div>
  </div>
  <svg viewBox="0 0 24 24" style="width:22px;height:22px;flex:none;fill:var(--secondary-text-color)"><path d="M8.6 16.6 13.2 12 8.6 7.4 10 6l6 6-6 6z"/></svg>
</div>`;
]]]

custom_fields.chip:
[[[
const st = id => states[id] ? states[id].state : undefined;
const sel = st('input_select.home_room') === variables.key;
const open = variables.open.some(id => st(id) === 'on');
const lit = variables.lights.some(id => st(id) === 'on');
const ink = sel ? 'var(--text-primary-color, #fff)' : 'color-mix(in srgb, rgb(from var(--primary-background-color) calc(255 - r) calc(255 - g) calc(255 - b)) 78%, var(--primary-text-color))';
const dot = open ? 'var(--error-color)' : lit ? 'var(--warning-color)' : '';
const t = parseFloat(st(variables.temp));
const c = variables.climate ? states[variables.climate] : null;
const a = c ? c.attributes : {};
const heating = !!c && c.state === 'heat' && (a.hvac_action === 'heating' || (a.power_percent || 0) > 0);
const tgt = c && c.state === 'heat' && a.temperature != null ? Math.round(a.temperature) : null;
const now = isNaN(t) ? null : Math.round(t);
const flame = '<svg viewBox="0 0 24 24" style="width:10px;height:10px;fill:var(--warning-color);margin-right:3px;vertical-align:-1px"><path d="M12 2c1 4 6 6.5 6 12a6 6 0 0 1-12 0c0-3 1.5-5 3-6.5.3 2 1.2 3.2 2.5 3.5C11 8 11.5 5 12 2z"/></svg>';
let line2 = now == null ? '&nbsp;' : `${now}°`;
if (now != null && heating) line2 = flame + line2 + (tgt != null && tgt > now ? ` → ${tgt}°` : '');
if (now != null && c && c.state === 'off') line2 += ' · off';
return `<div style="display:flex;flex-direction:column;align-items:center;line-height:1.2">
  <span style="position:relative;font-size:14px;font-weight:${sel ? 700 : 600};color:${ink}">${variables.key}${dot ? `<span style="position:absolute;top:1px;right:-8px;width:5px;height:5px;border-radius:50%;background:${dot}"></span>` : ''}</span>
  <span style="font-size:12px;font-weight:500;color:${ink};opacity:${sel ? 0.9 : 0.68};margin-top:3px;white-space:nowrap">${line2}</span>
</div>`;
]]]

card.box-shadow:
[[[
const sel = states['input_select.home_room'] && states['input_select.home_room'].state === variables.key;
const c = variables.climate ? states[variables.climate] : null;
const a = c ? c.attributes : {};
const heating = !!c && c.state === 'heat' && (a.hvac_action === 'heating' || (a.power_percent || 0) > 0);
const s = [];
if (!sel) s.push('inset 0 0 0 1px color-mix(in srgb, rgb(from var(--primary-background-color) calc(255 - r) calc(255 - g) calc(255 - b)) 14%, transparent)');
if (heating) s.push('inset 0 -3px 0 0 var(--warning-color)');
return s.length ? s.join(', ') : 'none';
]]]

