custom_fields.body:
[[[
const st = id => states[id] ? states[id].state : undefined;
const ic = (i, c) => `<ha-icon icon="${i}" style="--mdc-icon-size:16px;width:16px;height:16px;color:${c || 'inherit'}"></ha-icon>`;
const red = 'var(--error-color)';
const lit = variables.lights.filter(id => st(id) === 'on').length;
const ext = variables.read.filter(r => r[3] && st(r[0]) === 'on').map(r => r[2] || (r[1] === 'window' ? 'Window' : 'Door'));
const items = variables.read.map(r => {
  const [id, kind, label, isExt] = r;
  const s = st(id);
  const on = s === 'on';
  let h = '';
  if (kind === 'door') h = ic(on ? 'mdi:door-open' : 'mdi:door-closed', on && isExt ? red : '');
  else if (kind === 'window') h = ic(on ? 'mdi:window-open-variant' : 'mdi:window-closed-variant', on && isExt ? red : '');
  else if (kind === 'gate') h = ic(on ? 'mdi:gate-open' : 'mdi:gate', on ? red : '');
  else if (kind === 'temp') { const t = parseFloat(s); h = ic('mdi:thermometer') + (isNaN(t) ? '--' : Math.round(t) + '°'); }
  else if (kind === 'hum') { const v = parseFloat(s); h = ic('mdi:water-percent') + (isNaN(v) ? '--' : Math.round(v) + '%'); }
  else if (kind === 'motion') h = ic(on ? 'mdi:motion-sensor' : 'mdi:motion-sensor-off', on ? 'var(--warning-color)' : '');
  else if (kind === 'lux') h = ic('mdi:brightness-5') + (s === undefined ? '--' : s) + ' lx';
  else if (kind === 'set') { const a = (states[id] && states[id].attributes) || {}; const sp = parseFloat(a.temperature); h = s === 'off' ? ic('mdi:thermostat-off') + 'Off' : ic('mdi:thermostat') + (isNaN(sp) ? '--' : 'Set ' + Math.round(sp) + '°'); }
  return `<span style="display:inline-flex;align-items:center;gap:3px">${label ? `<span>${label}</span>` : ''}${h}</span>`;
});
variables.notes.filter(n => st(n[0]) === n[2]).forEach(n => items.push(`<span>${n[1]}</span>`));
let title, color = 'var(--primary-text-color)';
if (ext.length) { title = ext.join(', ') + ' open'; color = red; }
else if (variables.lights.length) title = lit ? lit + (lit === 1 ? ' light on' : ' lights on') : 'Lights off';
else title = variables.title;
const t = parseFloat(st(variables.big));
const big = variables.big ? (isNaN(t) ? '--' : Math.round(t)) + '°' : `<ha-icon icon="mdi:shower-head" style="--mdc-icon-size:30px;width:30px;height:30px;color:var(--secondary-text-color)"></ha-icon>`;
return `<div style="display:flex;align-items:center;gap:14px;width:100%">
  <div style="font-size:34px;font-weight:300;line-height:1;min-width:52px">${big}</div>
  <div style="flex:1;min-width:0;text-align:left">
    <div style="font-size:15px;font-weight:600;color:${color}">${title}</div>
    <div style="display:flex;flex-wrap:wrap;gap:3px 12px;margin-top:3px;font-size:12.5px;color:var(--secondary-text-color)">${items.join('')}</div>
  </div>
</div>`;
]]]

tap_action.javascript:
[[[
const ls = variables.lights;
const any = ls.some(id => states[id] && states[id].state === 'on');
hass.callService('light', any ? 'turn_off' : 'turn_on', { entity_id: ls });
]]]

custom_fields.row:
[[[
const ls = variables.lights;
const on = ls.filter(id => states[id] && states[id].state === 'on').length;
const any = on > 0;
const inv = 'rgb(from var(--primary-background-color) calc(255 - r) calc(255 - g) calc(255 - b))';
const ink = `color-mix(in srgb, ${inv} 78%, var(--primary-text-color))`;
const bulb = '<svg viewBox="0 0 24 24" style="width:22px;height:22px;flex:none;fill:' + (any ? 'var(--warning-color)' : ink) + ';opacity:' + (any ? 1 : 0.55) + '"><path d="M12,2A7,7 0 0,0 5,9C5,11.38 6.19,13.47 8,14.74V17A1,1 0 0,0 9,18H15A1,1 0 0,0 16,17V14.74C17.81,13.47 19,11.38 19,9A7,7 0 0,0 12,2M9,21A1,1 0 0,0 10,22H14A1,1 0 0,0 15,21V20H9V21Z"/></svg>';
const track = any ? 'var(--warning-color)' : `color-mix(in srgb, ${inv} 20%, transparent)`;
return `<div style="display:flex;align-items:center;gap:12px;width:100%">
  ${bulb}
  <div style="flex:1;min-width:0;text-align:left">
    <div style="font-size:14px;font-weight:600;color:${ink}">Room lights</div>
    <div style="font-size:12px;color:${ink};opacity:.65">${any ? on + ' of ' + ls.length + ' on' : 'All off'}</div>
  </div>
  <div style="width:46px;height:26px;border-radius:13px;background:${track};position:relative;flex:none;transition:background .2s">
    <div style="position:absolute;top:3px;left:${any ? 23 : 3}px;width:20px;height:20px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.35);transition:left .2s"></div>
  </div>
</div>`;
]]]

