custom_fields.body:
[[[
const st = id => states[id] ? states[id].state : undefined;
const NAMES = {idle: 'Clock', message: 'Message 1', message2: 'Message 2', notification: 'Notification', zags: 'Gonzaga',
  mariners: 'Mariners', seahawks: 'Seahawks', sounders: 'Sounders', kraken: 'Kraken', bedtime: 'Bedtime',
  alert: 'Pop-up alert', timer: 'Alexa timer', celebration: 'Score celebration'};
const on = st('input_boolean.panel_power') === 'on';
const bright = Math.round(parseFloat(st('input_number.panel_brightness')) || 0);
const mode = (st('sensor.led_matrix_panel_display_mode') || 'idle').toLowerCase();
const screen = NAMES[mode] || mode;
const override = st('input_select.panel_mode_override') || 'Auto';
const pinned = override !== 'Auto';
const frozen = st('input_boolean.panel_freeze_cycle') === 'on';
let title = screen, sub, color = 'var(--primary-text-color)', iconColor = '#5fc9b4';
if (!on) { title = 'Panel off'; sub = 'Tap to open the panel controls'; color = 'var(--secondary-text-color)'; iconColor = 'var(--disabled-text-color)'; }
else {
  const how = pinned ? 'Pinned to ' + (NAMES[override.toLowerCase()] || override) : frozen ? 'Rotation frozen' : 'Auto rotation';
  if (bright === 0) { title = 'Dark'; iconColor = 'var(--disabled-text-color)'; }
  if (pinned || frozen) color = 'var(--warning-color)';
  sub = how + ' · ' + bright + '% brightness';
}
return `<div style="display:flex;align-items:center;gap:16px;width:100%">
  <div style="width:44px;height:44px;border-radius:12px;background:#0c0c0c;display:grid;place-items:center;flex:none">
    <svg viewBox="0 0 24 24" style="width:24px;height:24px;fill:${iconColor}"><path d="M4 5h16a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2h-6v2h3v2H7v-2h3v-2H4a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2zm0 2v8h16V7H4zm2 2h2v2H6V9zm3 0h2v2H9V9zm3 0h2v2h-2V9zm3 0h2v2h-2V9zm-9 3h2v2H6v-2zm9 0h2v2h-2v-2z"/></svg>
  </div>
  <div style="flex:1;min-width:0;text-align:left">
    <div style="font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--secondary-text-color)">LED panel</div>
    <div style="font-size:15px;font-weight:600;color:${color};margin-top:2px">${title}</div>
    <div style="font-size:13px;color:var(--secondary-text-color);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${sub}</div>
  </div>
  <svg viewBox="0 0 24 24" style="width:22px;height:22px;flex:none;fill:var(--secondary-text-color)"><path d="M8.6 16.6 13.2 12 8.6 7.4 10 6l6 6-6 6z"/></svg>
</div>`;
]]]

cards.label:
[[[
  const phase = entity?.state ?? '—';
  const isPaused = phase === 'Paused';
  const isIdle = phase === 'Idle';
  const warnMin = Math.round(parseFloat(states['input_number.bedtime_warning_delay']?.state ?? '10'));
  const resolvePhase = (p) => p.includes('warning') ? `${warnMin} Min Warning` : p;

  // Build dynamic sequence from slot helpers
  const warningEnabled = states['input_boolean.bedtime_warning_enabled']?.state !== 'off';
  const slots = [
    states['input_select.bedtime_slot_2']?.state,
    states['input_select.bedtime_slot_3']?.state,
    states['input_select.bedtime_slot_4']?.state,
    states['input_select.bedtime_slot_5']?.state,
  ].filter(s => s && s !== 'None');
  const seq = [
    ...(warningEnabled ? ['10-min warning'] : []),
    ...slots,
    'Goodnight Liam!'
  ];
  const total = seq.length;

  const phaseEmojis = {
    '10-min warning': '⏰',
    'Jammies Time!': '🚿',
    'Books!': '📚',
    'Snuggle Time 1': '💕',
    'Snuggle Time 2': '🔄',
    'Goodnight Liam!': '😴',
  };

  if (isIdle) return 'Ready to begin';

  const pausedPhase = states['input_text.bedtime_pause_seconds']?.state ?? '';
  const effectivePhase = isPaused && pausedPhase ? pausedPhase : phase;
  const idx = seq.indexOf(effectivePhase);
  const stepLine = idx >= 0
    ? `${phaseEmojis[effectivePhase] ?? '📋'} Step ${idx + 1} of ${total}`
    : (phase === 'Paused' ? '⏸ Paused' : phase === 'Completed' ? '✅ Complete' : '');

  const remaining = isPaused
    ? (() => {
        const t = Math.round(states['input_datetime.bedtime_pause_remaining']?.attributes?.timestamp ?? 0);
        if (!t) return '—';
        const m = Math.floor(t / 60);
        const s = t % 60;
        return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
      })()
    : states['sensor.bedtime_phase_time_remaining']?.state ?? '—';

  const displayPhase = isPaused && pausedPhase
    ? `⏸ PAUSED - ${resolvePhase(pausedPhase)}`
    : resolvePhase(phase);

  return `${displayPhase}\n${stepLine}\n⏳ ${remaining} remaining`;
]]]

