custom_fields.moods:
[[[
  const mood = states['sensor.liams_clock_mood'].state;
  const moods = [
    { name: 'Happy',  icon: '😊', color: '#3B6D11', bg: '#EAF3DE', border: '#639922' },
    { name: 'Tired',  icon: '😴', color: '#185FA5', bg: '#E6F1FB', border: '#378ADD' },
    { name: 'Grumpy', icon: '😠', color: '#854F0B', bg: '#FAEEDA', border: '#BA7517' },
    { name: 'Sad',    icon: '😢', color: '#533AB7', bg: '#EEEDFE', border: '#7F77DD' },
  ];

  const tiles = moods.map(m => {
    const active = mood === m.name;
    return `<div style="
      background: ${active ? m.bg : 'var(--secondary-background-color)'};
      border: ${active ? '2px solid ' + m.border : '1px solid var(--divider-color)'};
      border-radius: 12px;
      padding: 14px 8px;
      text-align: center;
      opacity: ${active ? '1' : '0.55'};
      flex: 1;
      min-width: 0;
      box-sizing: border-box;
    ">
      <div style="font-size: 22px; margin-bottom: 6px;">${m.icon}</div>
      <div style="font-size: 13px; font-weight: 500; color: ${active ? m.color : 'var(--secondary-text-color)'};">${m.name}</div>
      ${active ? '<div style="width: 8px; height: 8px; border-radius: 50%; background: ' + m.border + '; margin: 6px auto 0;"></div>' : ''}
    </div>`;
  }).join('');

  return `<div style="display:flex; gap:10px; width:100%;">${tiles}</div>`;
]]]

