custom_fields.stars:
[[[
  const raw = (entity ? entity.state : '0').padEnd(28, '0').slice(0, 28);

  const dayColumns = Array.from({ length: 7 }, (_, dayIndex) => {
    const starStack = Array.from({ length: 4 }, (_, starIndex) => {
      const idx = (dayIndex * 4) + starIndex;
      const earned = raw[idx] === '1';

      return `
        <div style="
          text-align:center;
          font-size:22px;
          line-height:1;
          opacity:${earned ? '1' : '0.20'};
          color:${earned ? '#ffe08a' : 'rgba(255,255,255,0.40)'};
          text-shadow:${earned ? '0 0 10px rgba(255,223,138,0.45)' : 'none'};
        ">★</div>
      `;
    }).join('');

    return `
      <div style="
        flex:1;
        min-width:0;
        display:flex;
        flex-direction:column;
        gap:6px;
        align-items:center;
        justify-content:flex-start;
      ">
        ${starStack}
      </div>
    `;
  }).join('');

  return `
    <div style="
      display:flex;
      gap:6px;
      width:100%;
      align-items:flex-start;
    ">
      ${dayColumns}
    </div>
  `;
]]]

custom_fields.footer:
[[[
  const total = parseInt(states['input_number.liam_star_bank']?.state || 0);
  const goal = parseInt(states['input_number.liam_star_goal']?.state || 20);
  const remaining = Math.max(goal - total, 0);

  let text = '';
  if (total >= goal) text = 'Goal reached ✨ • Hold to reset';
  else if (remaining === 1) text = '1 more star to goal • Hold to reset';
  else text = `${remaining} more stars to goal • Hold to reset`;

  return `
    <div style="
      font-size:13px;
      color:rgba(255,255,255,0.78);
    ">
      ${text}
    </div>
  `;
]]]

